33: fn windows_metadata_wire_len(metadata: Option<&WindowsFileMetadata>) -> usize {
34:     match metadata {
35:         None => 1,
36:         Some(metadata) => 1usize
37:             .saturating_add(std::mem::size_of::<u32>())
38:             .saturating_add(metadata.encoded_len()),
