42: async fn write_windows_metadata<W: tokio::io::AsyncWrite + Unpin>(
43:     writer: &mut W,
44:     metadata: Option<&WindowsFileMetadata>,
45: ) -> Result<()> {
46:     let Some(metadata) = metadata else {
47:         writer
48:             .write_all(&[WINDOWS_METADATA_ABSENT])
49:             .await
50:             .context("writing Windows metadata presence")?;
51:         return Ok(());
52:     };
53:     crate::windows_metadata::validate_payload(Some(metadata))?;
54:     let encoded = metadata.encode_to_vec();
55:     if encoded.len() > MAX_WINDOWS_METADATA_WIRE_BYTES {
56:         bail!(
57:             "encoded Windows metadata is {} bytes, exceeds wire cap {}",
58:             encoded.len(),
59:             MAX_WINDOWS_METADATA_WIRE_BYTES
60:         );
61:     }
62:     writer
63:         .write_all(&[WINDOWS_METADATA_PRESENT])
64:         .await
65:         .context("writing Windows metadata presence")?;
66:     writer
67:         .write_all(&(encoded.len() as u32).to_be_bytes())
68:         .await
69:         .context("writing Windows metadata length")?;
70:     writer
71:         .write_all(&encoded)
72:         .await
73:         .context("writing Windows metadata")
74: }
