84: pub(crate) async fn read_windows_metadata_with_budget<R: tokio::io::AsyncRead + Unpin>(
85:     reader: &mut R,
86:     remaining_wire_bytes: usize,
87: ) -> Result<(Option<WindowsFileMetadata>, usize)> {
88:     if remaining_wire_bytes < 1 {
89:         bail!("Windows metadata exceeds remaining tar-shard header budget");
90:     }
91:     let presence = reader
92:         .read_u8()
93:         .await
94:         .context("reading Windows metadata presence")?;
95:     match presence {
96:         WINDOWS_METADATA_ABSENT => Ok((None, 1)),
97:         WINDOWS_METADATA_PRESENT => {
98:             const PREFIX_BYTES: usize = 1 + std::mem::size_of::<u32>();
99:             if remaining_wire_bytes < PREFIX_BYTES {
100:                 bail!("Windows metadata exceeds remaining tar-shard header budget");
101:             }
102:             let len = reader
103:                 .read_u32()
104:                 .await
105:                 .context("reading Windows metadata length")? as usize;
106:             if len > MAX_WINDOWS_METADATA_WIRE_BYTES {
107:                 bail!(
108:                     "encoded Windows metadata is {} bytes, exceeds wire cap {}",
109:                     len,
110:                     MAX_WINDOWS_METADATA_WIRE_BYTES
111:                 );
112:             }
113:             if len > remaining_wire_bytes - PREFIX_BYTES {
114:                 bail!(
115:                     "encoded Windows metadata is {} bytes, exceeds remaining tar-shard header budget {}",
116:                     len,
117:                     remaining_wire_bytes - PREFIX_BYTES
118:                 );
119:             }
120:             let mut encoded = vec![0u8; len];
121:             reader
122:                 .read_exact(&mut encoded)
123:                 .await
124:                 .context("reading Windows metadata")?;
125:             let metadata = WindowsFileMetadata::decode(encoded.as_slice())
126:                 .context("decoding Windows metadata")?;
127:             crate::windows_metadata::validate_payload(Some(&metadata))?;
128:             Ok((Some(metadata), PREFIX_BYTES + len))
129:         }
130:         other => bail!("invalid Windows metadata presence tag {other}"),
131:     }
132: }
