134: fn tar_shard_header_wire_bytes(headers: &[FileHeader]) -> Result<usize> {
135:     let mut total = std::mem::size_of::<u32>();
136:     for header in headers {
137:         let fixed = std::mem::size_of::<u32>()
138:             + header.relative_path.len()
139:             + std::mem::size_of::<u64>()
140:             + std::mem::size_of::<i64>()
141:             + std::mem::size_of::<u32>();
142:         total = total
143:             .checked_add(fixed)
144:             .and_then(|value| {
145:                 value.checked_add(windows_metadata_wire_len(header.windows_metadata.as_ref()))
146:             })
147:             .ok_or_else(|| eyre::eyre!("tar-shard header byte count overflow"))?;
148:         if total > MAX_TAR_SHARD_HEADER_WIRE_BYTES {
149:             bail!(
150:                 "tar-shard headers are {} bytes, exceed aggregate cap {}",
151:                 total,
152:                 MAX_TAR_SHARD_HEADER_WIRE_BYTES
153:             );
154:         }
155:     }
156:     Ok(total)
157: }
